import pandas as pd

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    """
    Reproduces legacy partition refresh ETL:
    1. CREATE STG_NEW: aggregate inbound data (qty > 0) by product_id, batch_date
    2. DELETE from target_snapshot: remove all rows matching arriving batch_dates
    3. INSERT into target_snapshot: add aggregated rows from STG_NEW
    """

    inbound = inputs.get('inbound', pd.DataFrame())
    target_snapshot = inputs.get('target_snapshot', pd.DataFrame()).copy()

    # Step 1: Create STG_NEW by aggregating inbound where qty > 0
    stg_new = inbound[inbound['qty'] > 0].copy()

    if len(stg_new) > 0:
        stg_new = stg_new.groupby(['product_id', 'batch_date'], as_index=False).agg({
            'total_qty': 'sum',
            'max_unit_cost': 'max'
        })
        # Handle case where agg columns might be named differently in input
        if 'total_qty' not in stg_new.columns and 'qty' in stg_new.columns:
            stg_new = stg_new.rename(columns={'qty': 'total_qty'})
        if 'max_unit_cost' not in stg_new.columns and 'unit_cost' in stg_new.columns:
            stg_new = stg_new.rename(columns={'unit_cost': 'max_unit_cost'})
    else:
        # Empty result with correct schema
        stg_new = pd.DataFrame(columns=['product_id', 'batch_date', 'total_qty', 'max_unit_cost'])

    # Step 2: Delete from target_snapshot rows with batch_dates in STG_NEW
    if len(stg_new) > 0:
        arriving_batch_dates = stg_new['batch_date'].unique()
        target_snapshot = target_snapshot[~target_snapshot['batch_date'].isin(arriving_batch_dates)]

    # Step 3: Insert rows from STG_NEW into target_snapshot
    if len(stg_new) > 0:
        target_snapshot = pd.concat([target_snapshot, stg_new], ignore_index=True)

    # Ensure correct column order and types
    if len(target_snapshot) > 0:
        target_snapshot = target_snapshot[['product_id', 'batch_date', 'total_qty', 'max_unit_cost']]

    return {'target_snapshot': target_snapshot}
